<?php $editing=!empty($address);$cancel=$returnPath?:'/minha-conta/enderecos';?><div class="dashboard-heading"><div><span class="eyebrow">ENDEREÇO</span><h2><?=$editing?'Editar endereço':'Novo endereço'?></h2><p><?= $returnPath==='/checkout'?'Cadastre onde deseja receber e volte ao checkout.':'Mantenha seus locais de entrega organizados.' ?></p></div></div><form class="panel resource-form" method="post" action="<?=e($editing?url('/minha-conta/enderecos/'.$address['id']):url('/minha-conta/enderecos'))?>"><?=csrf_field()?><?php if($editing):?><input type="hidden" name="_method" value="PUT"><?php endif;?><?php if($returnPath):?><input type="hidden" name="return" value="<?=e($returnPath)?>"><?php endif;?><div class="form-grid"><label>Identificação<input name="label" value="<?=e($address['label']??'')?>" placeholder="Casa, trabalho..."></label><label>Destinatário<input name="recipient_name" required value="<?=e($address['recipient_name']??$authUser['name']??'')?>"></label><label>CEP<input name="postal_code" data-mask="cep" inputmode="numeric" required value="<?=e($address['postal_code']??'')?>"></label><label>Rua<input name="street" required value="<?=e($address['street']??'')?>"></label><label>Número<input name="number" required value="<?=e($address['number']??'')?>"></label><label>Complemento<input name="complement" value="<?=e($address['complement']??'')?>"></label><label>Bairro<input name="neighborhood" required value="<?=e($address['neighborhood']??'')?>"></label><label>Cidade<input name="city" required value="<?=e($address['city']??'')?>"></label><label>UF<input name="state" required maxlength="2" value="<?=e($address['state']??'')?>"></label><label class="checkbox"><input type="checkbox" name="is_default" value="1" <?=!empty($address['is_default'])?'checked':''?>>Endereço principal</label></div><div class="form-actions"><a class="button button--secondary" href="<?=e(url($cancel))?>">Cancelar</a><button class="button button--primary">Salvar endereço</button></div></form>
